<?php
declare(strict_types=1);
require_once __DIR__.'/pdf.php';
function ct_catalog():array{return json_decode(file_get_contents(__DIR__.'/package/catalog.json'),true,512,JSON_THROW_ON_ERROR)['templates'];}
function ct_import(array $a):array{
 cc_owner($a);$ids=[];foreach(ct_catalog() as $item){if(hash_file('sha256',__DIR__.'/package/'.$item['file'])!==$item['sha256'])crm_fail(503,'Исходный шаблон повреждён.');$clauses=['_package'=>$item];$hash=hash('sha256',lc_json([$item['kind'],$item['title'],$clauses]));$id=crm_query('SELECT id FROM nd_lc_templates WHERE checksum=?',[$hash])->fetchColumn();if(!$id){$n=(int)crm_query('SELECT COALESCE(MAX(revision_number),0)+1 FROM nd_lc_templates WHERE kind=?',[$item['kind']])->fetchColumn();crm_query("INSERT INTO nd_lc_templates(kind,revision_number,title,clauses_json,checksum,state) VALUES (?,?,?,?,?,'NEEDS_LEGAL_REVIEW')",[$item['kind'],$n,$item['title'],lc_json($clauses),$hash]);$id=(int)db()->lastInsertId();lc_audit($a,'template',$id,'package_imported',null,['source_sha256'=>$item['sha256'],'approval_inferred'=>false]);}$ids[]=(int)$id;}return ['ok'=>true,'id'=>$ids[0],'ids'=>$ids];
}
function ct_fill(array $item,array $fields):array{
 $optional=['owner.postal_address_line','review.rating','review.company','review.photo_reference'];$out=[];
 foreach($item['fields'] as $key){if(in_array($key,$optional,true)&&!array_key_exists($key,$fields))$fields[$key]='';$v=$fields[$key]??null;if(!is_string($v)||mb_strlen($v)>24000||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]|\{\{|\}\}|<\?(?:php|=)|-----BEGIN .*PRIVATE KEY|(?:password|secret|token)\s*[=:]/iu',$v)||(!in_array($key,$optional,true)&&trim($v)===''))crm_fail(422,'Не разрешено поле: '.$key);}
 foreach($item['paragraphs'] as $p){foreach(['review.rating'=>'Оценка при желании','review.company'=>'Компания при желании','review.photo_reference'=>'Фото при желании'] as $optionalKey=>$label)if(($fields[$optionalKey]??null)==='')$p=str_replace($label.' {{'.$optionalKey.'}}.','',$p);if(str_contains($p,'{{owner.postal_address_line}}')&&$fields['owner.postal_address_line']==='')continue;$p=preg_replace_callback('/\{\{([^{}]+)\}\}/',fn($m)=>$fields[$m[1]],$p);if(str_contains($p,'{{')||str_contains($p,'}}'))crm_fail(422,'Остались неразрешённые поля.');$out[]=$p;}return $out;
}
function ct_asset(array $b):array{$x=crm_query('SELECT * FROM nd_lc_pdf_assets WHERE binding_id=?',[$b['id']])->fetch();if(!$x||!hash_equals($x['source_hash'],$b['generated_hash']))crm_fail(404,'Для этой версии PDF не выпущен.');return $x;}
function ct_download(array $b):never{$x=ct_asset($b);$path=cc_file_path($x);header('Cache-Control: private, no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="document-'.$b['id'].'.pdf"');header('Content-Length: '.$x['size_bytes']);readfile($path);exit;}
function ct_store_pdf(int $id,string $source,string $bytes):void {
 $root=cc_storage(true);$lock=fopen($root.'/.quota.lock','c');if(!$lock||!flock($lock,LOCK_EX))crm_fail(503,'Хранилище занято.');$path=null;
 try{$used=0;foreach(new DirectoryIterator($root) as $e){if($e->isDot()||$e->getFilename()==='.quota.lock')continue;if($e->isLink()||!$e->isFile())crm_fail(503,'Проверьте хранилище.');$used+=$e->getSize();}cc_capacity($used,strlen($bytes),min(536870912,max(1,(int)(config()['collaboration_total_max_bytes']??104857600))),disk_free_space($root));$key=bin2hex(random_bytes(32));$path=$root.'/'.$key;$h=fopen($path,'x');if(!$h)crm_fail(503,'PDF не сохранён.');chmod($path,0600);$n=fwrite($h,$bytes);fclose($h);if($n!==strlen($bytes))crm_fail(503,'PDF не сохранён.');crm_query('INSERT INTO nd_lc_pdf_assets(binding_id,storage_key,checksum,size_bytes,source_hash) VALUES (?,?,?,?,?)',[$id,$key,hash('sha256',$bytes),strlen($bytes),$source]);}catch(Throwable $e){if($path&&is_file($path))unlink($path);throw $e;}finally{flock($lock,LOCK_UN);fclose($lock);}
}
